// Checks the incoming request. Nothing is drafted or sent if this fails.
const s = $('Settings').first().json;
const b = $('New draft request').first().json.body ?? {};
const str = (v) => (typeof v === 'string' ? v.trim() : '');
const clientId = str(b.client_id);
const task = str(b.task);
const recipient = str(b.recipient_email);

let error = null;
if (!clientId || clientId.length > 100) error = 'client_id is missing or longer than 100 characters';
else if (!task) error = 'task is missing';
else if (task.length > Number(s.max_task_chars)) error = `task is longer than ${s.max_task_chars} characters`;
else if (!/^[^\s@<>,;]+@[^\s@<>,;]+\.[^\s@<>,;]+$/.test(recipient)) error = 'recipient_email is missing or invalid';

return [{ json: {
  valid: error === null,
  error,
  client_id: clientId,
  task,
  recipient_email: recipient,
  subject: str(b.subject).slice(0, 200) || 'Your message',
  reference: str(b.reference).slice(0, 100),
} }];

// Combines the request, Settings and the client's row into one state object.
// That state travels through every later step, including the waits.
const s = $('Settings').first().json;
const req = $('Validate request').first().json;
const c = $input.first().json ?? {};

let httpStatus = 202;
let error = null;
const approvalRequired = c.approval_required !== false; // empty counts as "approval required"
if (c.client_id !== req.client_id) { httpStatus = 404; error = 'unknown_client'; }
else if (c.active === false) { httpStatus = 403; error = 'client_inactive'; }
else if (approvalRequired && !/^[^\s@<>,;]+@[^\s@<>,;]+\.[^\s@<>,;]+$/.test(String(c.approver_email ?? '').trim())) { httpStatus = 409; error = 'client_has_no_valid_approver_email'; }

const now = new Date().toISOString();
const requestId = `${req.client_id}-${$execution.id}`;
return [{ json: {
  ok: error === null,
  http_status: httpStatus,
  error,
  request_id: requestId,
  reference: req.reference || requestId,
  task: req.task,
  recipient_email: req.recipient_email,
  subject: req.subject,
  client: {
    client_id: req.client_id,
    client_name: String(c.client_name ?? '') || req.client_id,
    approver_email: String(c.approver_email ?? '').trim(),
    instructions: String(c.instructions ?? ''),
    approval_required: approvalRequired,
  },
  cfg: {
    company_name: s.company_name,
    sender: s.sender,
    expiry_hours: Number(c.expiry_hours) > 0 ? Number(c.expiry_hours) : Number(s.default_expiry_hours),
    reminder_before_hours: Number(s.reminder_before_hours) || 0,
    max_rounds: Math.max(1, Number(s.max_rounds) || 1),
    max_iterations: Math.max(1, Number(s.max_iterations) || 1),
    system_message: s.system_message,
  },
  status: 'drafting',
  decision: '',
  action_status: 'not_run',
  round: 1,
  approver: approvalRequired ? String(c.approver_email ?? '').trim() : '',
  draft: '',
  previous_draft: '',
  change_request: '',
  history: [`${now} request received`],
  state_at: Date.now(),
} }];

// Round 1 drafts from the task. Later rounds revise the draft with the approver's requested changes.
// Input is either the first request (after "Accept request") or a "Request changes" answer.
const st = $json.cfg ? $json : $('Check client').first().json;
const who = st.client.client_name || st.client.client_id;

let prompt = `Message received for ${who}:
<message>
${st.task}
</message>

Write the reply to this message.`;
if (st.round > 1) {
  prompt += `

Your previous draft:
<previous_draft>
${st.previous_draft}
</previous_draft>

Requested changes from ${who}'s approver:
<changes>
${st.change_request}
</changes>

Rewrite the reply so that it follows the requested changes.`;
}

return [{ json: { ...st, prompt, status: 'drafting', state_at: Date.now() } }];

// Takes the agent's text and stops on an empty draft (the error output goes to the failure path).
const st = $('Build the prompt').last().json;
const draft = String($json.output ?? '').replace(/\r\n/g, '\n').trim();
if (!draft) throw new Error('The AI agent returned an empty draft');
const { prompt, ...rest } = st;
return [{ json: { ...rest, draft, state_at: Date.now() } }];

// This client's row has approval_required = false, so the draft is sent without a form.
// The decision is still recorded with the fingerprint of what was sent.
const st = $json;
const now = new Date().toISOString();
return [{ json: {
  ...st,
  outcome: 'approved',
  status: 'approved',
  decision: 'approved_by_setting',
  action_status: 'pending',
  approved_text: st.draft,
  edited_by_approver: false,
  decided_by: 'client setting (approval_required = false)',
  decided_at: now,
  comment: '',
  history: [...st.history, `${now} no approval required for this client`],
  state_at: Date.now(),
} }];

// Sets this round's deadline and, if there is room, a reminder before it.
const st = $json;
const now = Date.now();
const expires = new Date(now + st.cfg.expiry_hours * 3600e3);
const remindMs = st.cfg.reminder_before_hours * 3600e3;
const reminderAt = remindMs > 0 && expires.getTime() - remindMs > now + 60e3 ? new Date(expires.getTime() - remindMs) : null;

return [{ json: {
  ...st,
  status: 'waiting',
  expires_at: expires.toISOString(),
  phase: reminderAt ? 'first' : 'final',
  reminded: false,
  wait_until: (reminderAt ?? expires).toISOString(),
  history: [...st.history, `${new Date(now).toISOString()} round ${st.round} sent to ${st.client.approver_email}`],
  state_at: now,
} }];

const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
// Builds the email to the approver (first email or reminder). Client text is HTML-escaped.
const st = $json;
const multi = (t) => esc(t).replace(/\n/g, '<br>');
const expiresText = st.expires_at.slice(0, 16).replace('T', ' ') + ' UTC';
const who = esc(st.client.client_name);
const subject = st.reminded
  ? `Reminder: please review the reply to "${st.subject}"`
  : `Please review: reply to "${st.subject}"${st.round > 1 ? ` (version ${st.round})` : ''}`;

const html = `<p>Hello,</p>
<p>${esc(st.cfg.company_name)} has drafted a reply on behalf of ${who}. Nothing is sent until you approve it.</p>
<p><strong>Message received</strong><br>${multi(st.task)}</p>
<p><strong>Proposed reply${st.round > 1 ? ` (version ${st.round})` : ''}</strong></p>
<div style="border-left:3px solid #999;padding:4px 12px;margin:8px 0">${multi(st.draft)}</div>
<p><a href="%%LINK%%">Open the review form</a> to approve it, edit it, ask for changes or reject it.</p>
<p>The link works until ${expiresText}. If there is no answer by then, the request expires and nothing is sent.</p>
<p style="color:#666">Reference: ${esc(st.reference)}</p>`;

return [{ json: { ...st, email_subject: subject, email_html: html, expires_text: expiresText, task_html: multi(st.task), state_at: Date.now() } }];

// The Wait node needs the full state as its input; the email and table steps return their own data.
// "Prepare the approval email" always holds the state of the current round.
// After an answer from an older form, keep that note in the history and wait again.
const st = $('Prepare the approval email').last().json;
const input = $input.first().json;
return [{ json: input.outcome === 'stale' ? { ...st, history: input.history } : st }];

// Turns the form answer, or the end of a waiting period, into one outcome.
// A timeout never counts as approval.
const st = $('Hold for decision').last().json;
const r = $input.first().json;
const now = new Date().toISOString();
const norm = (t) => String(t ?? '').replace(/\r\n/g, '\n').trim();
const base = { ...st, comment: '', state_at: Date.now() };

if (!r.submittedAt) {
  if (st.phase === 'first') {
    return [{ json: { ...base, outcome: 'remind', phase: 'final', reminded: true, wait_until: st.expires_at,
      history: [...st.history, `${now} no answer yet, reminder sent`] } }];
  }
  return [{ json: { ...base, outcome: 'expired', status: 'closed', decision: 'expired', action_status: 'not_run',
    decided_by: 'deadline', decided_at: now, history: [...st.history, `${now} expired without an answer`] } }];
}

// The form carries the fingerprint of the draft it showed. An answer from an older
// version of the form (for example a tab left open before a revision) is ignored.
if (String(r.draft_sha256 ?? '') !== st.draft_sha256) {
  return [{ json: { ...base, outcome: 'stale', history: [...st.history, `${now} ignored an answer from an older version of the form`] } }];
}

const choice = String(r['Decision'] ?? '');
const text = norm(r['Reply text']);
const comment = norm(r['Comment']).slice(0, 2000);
const by = st.client.approver_email;
const answered = { ...base, comment, decided_by: by, decided_at: now };

if (choice === 'Approve and send' && text) {
  const edited = text !== st.draft;
  return [{ json: { ...answered, outcome: 'approved', status: 'approved', decision: edited ? 'approved_with_edits' : 'approved',
    action_status: 'pending', approved_text: text, edited_by_approver: edited,
    history: [...st.history, `${now} approved${edited ? ' with edits' : ''} by ${by}`] } }];
}
if (choice === 'Request changes') {
  if (st.round >= st.cfg.max_rounds) {
    return [{ json: { ...answered, outcome: 'revision_limit', status: 'closed', decision: 'revision_limit', action_status: 'not_run',
      history: [...st.history, `${now} changes requested after the last allowed version`] } }];
  }
  const edited = text && text !== st.draft;
  return [{ json: { ...answered, outcome: 'changes', status: 'drafting', decision: 'changes_requested', round: st.round + 1,
    previous_draft: edited ? text : st.draft,
    change_request: comment || (edited ? 'The approver edited the text. Keep their edits and polish the wording.' : 'Improve the draft.'),
    history: [...st.history, `${now} changes requested by ${by}`] } }];
}
return [{ json: { ...answered, outcome: 'rejected', status: 'closed', decision: 'rejected', action_status: 'not_run',
  history: [...st.history, `${now} rejected by ${by}`] } }];

// Picks the state back up after the table write.
const st = $('Fingerprint the answer').last().json;
return [{ json: { ...st, approved_sha256: st.outcome === 'approved' ? st.approved_sha256 : '' } }];

