// Something failed. This path never runs the approved action.
const item = $input.first().json;
let st = item.request_id ? item : null;
if (!st) {
  // Data table and Code errors carry only the error, not the state: use the newest state.
  st = ['Fingerprint the answer', 'Prepare the approval email', 'Build the prompt']
    .filter((n) => $(n).isExecuted)
    .map((n) => $(n).last().json)
    .sort((a, b) => (b.state_at || 0) - (a.state_at || 0))[0] ?? {};
}
const textChanged = item.request_id && item.sent_sha256 && item.sent_sha256 !== item.approved_sha256;
const message = textChanged
  ? 'The text to send is not the approved text, so it was not sent'
  : String(item.error?.message ?? item.error ?? 'Unknown error').slice(0, 500);
const wasApproved = st.status === 'approved';
const sendFailed = $('Send the approved reply').isExecuted; // the send step ran and returned an error
const now = new Date().toISOString();
return [{ json: {
  ...st,
  status: 'closed',
  decision: wasApproved ? st.decision : 'error',
  action_status: textChanged ? 'blocked' : sendFailed ? 'failed' : 'not_run',
  error_message: message,
  history: [...(st.history ?? []), `${now} failed: ${message}`],
} }];

