// Lists requests that wait for an approver. Optional filter: ?client_id=
const clientId = String($('Pending requests').first().json.query?.client_id ?? '');
const now = new Date().toISOString();
const rows = $input.all().map((i) => i.json).filter((r) => r.request_id);

const waiting = rows
  .filter((r) => !clientId || r.client_id === clientId)
  .map((r) => ({ request_id: r.request_id, client_id: r.client_id, reference: r.reference, subject: r.subject,
    version: r.round, approver: r.approver, expires_at: r.expires_at, overdue: !!r.expires_at && r.expires_at < now }))
  .sort((a, b) => String(a.expires_at).localeCompare(String(b.expires_at)));
return [{ json: { count: waiting.length, waiting } }];

// One email a day with every request still waiting. No email when nothing is waiting.
const now = new Date().toISOString();
const rows = $input.all().map((i) => i.json).filter((r) => r.request_id);

if (rows.length === 0) return [];
const soon = new Date(Date.now() + 24 * 3600e3).toISOString();
rows.sort((a, b) => String(a.expires_at).localeCompare(String(b.expires_at)));
const lines = rows.map((r) => `- ${r.client_id} · ${r.reference} · "${r.subject}" · version ${r.round} · expires ${String(r.expires_at).slice(0, 16).replace('T', ' ')} UTC${r.expires_at < soon ? ' (within 24 hours)' : ''}`);
return [{ json: { count: rows.length, text: `${rows.length} request(s) are waiting for an approver:\n\n${lines.join('\n')}` } }];
